use std::collections::HashMap;

struct Solution;

impl Solution {
    pub fn max_equal_freq(nums: Vec<i32>) -> i32 {
        let mut freq = HashMap::new(); // number -> count
        let mut count_freq = HashMap::new(); // count -> how many numbers have this count
        let mut max_len = 0;

        for i in 0..nums.len() {
            let x = nums[i];
            let old_count = *freq.get(&x).unwrap_or(&0);
            if old_count > 0 {
                *count_freq.get_mut(&old_count).unwrap() -= 1;
                if count_freq[&old_count] == 0 {
                    count_freq.remove(&old_count);
                }
            }
            let new_count = old_count + 1;
            freq.insert(x, new_count);
            *count_freq.entry(new_count).or_insert(0) += 1;

            // Check conditions for prefix length i+1
            // Conditions for valid prefix after removing exactly one element:
            // Let:
            //   - k = number of distinct counts in count_freq
            //   - total numbers in prefix = i+1
            //   - freq map: number -> count
            //   - count_freq map: count -> how many numbers have this count

            if count_freq.len() == 1 {
                // Only one count c
                let (&c, &cnt) = count_freq.iter().next().unwrap();
                // Either c == 1 (remove one element from one number with count 1)
                // or cnt == 1 (remove one element from the single number with count c)
                if c == 1 || cnt == 1 {
                    max_len = (i + 1) as i32;
                }
            } else if count_freq.len() == 2 {
                // Two distinct counts
                let mut iter = count_freq.iter();
                let (&c1, &cnt1) = iter.next().unwrap();
                let (&c2, &cnt2) = iter.next().unwrap();

                // Sort so c1 < c2
                let (c1, cnt1, c2, cnt2) = if c1 < c2 {
                    (c1, cnt1, c2, cnt2)
                } else {
                    (c2, cnt2, c1, cnt1)
                };

                // Two possible valid cases:
                // 1) c1 == 1 and cnt1 == 1
                //    (remove the one element with count 1)
                // 2) c2 == c1 + 1 and cnt2 == 1
                //    (remove one element from the number with count c2 to make all counts equal c1)
                if (c1 == 1 && cnt1 == 1) || (c2 == c1 + 1 && cnt2 == 1) {
                    max_len = (i + 1) as i32;
                }
            }
        }

        max_len
    }
}

